{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret siger, at arbejdsprøvning 'kan indgå ... som et muligt bevis'. Kilden siger, at arbejdsprøvning, særlig arbejdspladsindretning eller lignende ikke indgår. Det samme gælder for særlig arbejdspladsindretning, som svaret siger 'kan indgå', hvis tilpasningerne er konkrete og realistiske. Svaret siger også, at oplysninger fra en arbejdsgiver 'kan være relevante', selv om Udbetaling Danmark ikke kontakter arbejdsgivere. Endelig siger det, at kommunale vurderinger kan indgå 'som dokumentation' uden støtte i kilden. Det er væsentlige juridiske fejl. Rubrikken nævner netop, at arbejdsprøvning eller særlig indretning ikke må gøres til et led. Svaret får dog rigtigt, at kommunal arbejdsevnevurdering ikke er målestokken, og at studierelevans, lokale jobmuligheder og erhvervsevnen efter uddannelsen ikke indgår."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker målestokken, at den kommunale vurdering ikke er samme målestok, studierelevans, lokale forhold og erhvervsevnen efter uddannelsen. Det mangler det kritiske element om, at arbejdsprøvning og særlig arbejdspladsindretning ikke indgår, og at Udbetaling Danmark ikke kontakter arbejdsgivere. Svaret siger tværtimod, at de kan indgå."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret tager stilling til alle syv forhold i spørgsmålet i en tabel, og det er direkte relevant. At nogle af svarene er forkerte, er et spørgsmål om rigtighed og ikke om relevans."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, vejledningsafsnit eller lignende. Det nævner kun 'SU-reglerne' og 'sociallovgivningen' generelt."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde støtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer regler uden støtte i materialet. Arbejdsprøvning kan være bevis. Konkrete og realistiske tilpasninger af arbejdspladsen kan indgå. Arbejdsgiveroplysninger kan være relevante. Kommunale vurderinger kan indgå som dokumentation. Prognosen kan have betydning for varighed er muligvis i tråd med bekendtgørelsens § 36, stk. 2, men den øvrige tilføjelse modsiger kilden. Formuleringen 'nærmest ude af stand' er ikke direkte støttet af passagerne, som taler om 'meget betydelige begrænsninger'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke den vigtige undtagelse om, at arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiverkontakt ikke indgår. Det udvander den i stedet til 'kan indgå' eller 'kan være relevant'. Det bevarer dog, at erhvervsevnen efter uddannelsen ikke er målestokken."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret siger, at vurderingen er SU-styrelsens egen og ikke den kommunale, men lader samtidig arbejdsprøvning, særlig indretning og arbejdsgiverkontakt indgå. Det er ikke i overensstemmelse med, at der kun tages stilling til evnen til erhvervsarbejde med de ressourcer, personen har. Resumeet om 'konkrete oplysninger om arbejdspladsforhold' som relevant dokumentation hænger heller ikke sammen med, at lokale forhold og studierelevans ikke indgår."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Det, som kilden udelukker ('indgår ikke'), er i svaret gjort til noget, der 'kan indgå' eller 'kan være relevant'. Udelukkelsen er dermed svækket til et skøn. 'Normalt nej' og 'som udgangspunkt nej' bruges om studierelevans, lokale forhold og erhvervsevne efter uddannelsen, hvor kilden er kategorisk ('indgår ikke')."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker, at vurderingen angår evnen til erhvervsarbejde ved siden af uddannelsen, at studierelevans, lokale forhold og erhvervsevnen efter uddannelsen ikke indgår. Det nævner dog ikke de meget betydelige begrænsninger og ordblindeeksemplet. Det modsiger desuden kilden på arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiverkontakt og gengiver ikke, at vanskeligheder med at finde arbejde ikke indgår som sådan."
    }
  },
  "overall_notes": "Svaret er velstruktureret og besvarer alle dele af spørgsmålet. Det giver dog et væsentligt forkert svar på arbejdsprøvning, særlig arbejdspladsindretning og arbejdsgiverkontakt, som ifølge vejledningen ikke indgår. Der er ingen kildeangivelse, så C04 er not_met, og C05 og C06 er not_assessable."
}

